{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name AS caller_svc, c.span_name AS caller_span, s.span_name AS callee_span, s.attr_http_request_method AS method, s.attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'ts-travel-plan-service' AND s.service_name = 'ts-route-plan-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "In the abnormal period travel-plan's calls to route-plan arrive as OPTIONS /* (1447, status 200) and no quickestRoute POSTs remain."
        },
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, s.attr_http_request_method AS method, s.attr_http_response_status_code AS code, count(*) AS n FROM normal_traces s JOIN normal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'ts-travel-plan-service' AND s.service_name = 'ts-route-plan-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "In the normal period travel-plan calls route-plan as POST .../routePlan/quickestRoute (62 calls), with no OPTIONS calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces WHERE span_name = 'POST /api/v1/travelplanservice/travelPlan/quickest' GROUP BY ALL ORDER BY n DESC",
          "claim": "travel-plan's quickest endpoint returns 500 on 1447 requests in the abnormal period; the dashboard's quickest calls fail with 500 as well."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) AS n FROM abnormal_logs WHERE level = 'SEVERE' GROUP BY ALL ORDER BY n DESC",
          "claim": "ts-travel-plan-service emits 1447 SEVERE logs in the abnormal period, matching its failed quickest requests; no SEVERE logs in the normal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS code, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE span_name = 'POST /api/v1/travelplanservice/travelPlan/quickest' GROUP BY ALL ORDER BY n DESC",
          "claim": "The dashboard's quickest calls to travel-plan return 500 (82 spans, p95 about 4 s) in the abnormal period, while travel-plan's own quickest spans fail fast."
        }
      ]
    }
  ]
}
